mapper.select:
SELECT model_id, model_code, model_name, adapter_type, task_type, weights_path, labels_json::text AS labels_json, conf_threshold, iou_threshold, vlm_review_enabled, vlm_trigger_conf, applicable_places, is_default, status, remark, create_by, create_time, update_time FROM ehs_vision_model
AND model_name ILIKE '%' || #{modelName} || '%' AND adapter_type = #{adapterType} AND status = #{status}
ORDER BY is_default DESC, model_id ASC

mapper.update:
UPDATE ehs_vision_model
model_name = #{modelName}, adapter_type = #{adapterType}, task_type = #{taskType}, weights_path = #{weightsPath}, labels_json = CAST(#{labelsJson} AS jsonb), conf_threshold = #{confThreshold}, iou_threshold = #{iouThreshold}, vlm_review_enabled = #{vlmReviewEnabled}, vlm_trigger_conf = #{vlmTriggerConf}, applicable_places = #{applicablePlaces}, is_default = #{isDefault}, status = #{status}, remark = #{remark}, update_time = CURRENT_TIMESTAMP
WHERE model_id = #{modelId}

mapper.select:
SELECT p.point_id, p.point_code, p.point_name, p.place_type, p.dept_id, d.dept_name, p.hazard_id, h.hazard_name, p.default_model_id, m.model_code AS default_model_code, p.stream_protocol, p.stream_url, p.map_x, p.map_y, p.status, p.create_time FROM ehs_camera_point p LEFT JOIN sys_dept d ON p.dept_id = d.dept_id LEFT JOIN ehs_hazard_profile h ON p.hazard_id = h.hazard_id LEFT JOIN ehs_vision_model m ON p.default_model_id = m.model_id
AND p.place_type = #{placeType} AND p.dept_id = #{deptId} AND p.status = #{status}
ORDER BY p.point_id ASC

SELECT a.alert_id, a.alert_no, a.point_id, p.point_name, a.dept_id, d.dept_name,
       a.place_type, a.model_code, a.prompt_text, a.raw_image_url, a.annotated_image_url,
       a.detections_json::text AS detections_json, a.inference_ms, a.vlm_reviewed, a.vlm_model,
       a.is_real_hazard, a.violation_type, a.severity, a.vlm_description, a.vlm_suggestion,
       a.cited_laws_json::text AS cited_laws_json, a.handle_status, a.order_id, a.create_by, a.create_time
FROM ehs_vision_alert a
LEFT JOIN sys_dept d ON a.dept_id = d.dept_id
LEFT JOIN ehs_camera_point p ON a.point_id = p.point_id

    AND a.place_type = #{placeType}
    AND a.dept_id = #{deptId}
    AND a.severity = #{severity}
    AND a.handle_status = #{handleStatus}
    AND a.is_real_hazard = #{isRealHazard}

ORDER BY a.alert_id DESC

mapper.update:
UPDATE ehs_vision_alert
handle_status = #{handleStatus}, order_id = #{orderId}, update_time = CURRENT_TIMESTAMP
WHERE alert_id = #{alertId}
